import React, { useEffect, useState } from 'react';

const rawLines = [
  ['name', '=', '"Chetanya Makkar"'],
  ['major', '=', '"Computer Science"'],
  ['minor', '=', '"Computational Finance"'],
  ['gpa', '=', '3.76'],
  ['school', '=', '"University of Maryland"']
];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState('');
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);

  // Combine tokens into full strings
  const lines = rawLines.map(parts => parts.join(' '));

  useEffect(() => {
    if (lineIndex < lines.length) {
      if (charIndex < lines[lineIndex].length) {
        const timeout = setTimeout(() => {
          setCurrentLine(prev => prev + lines[lineIndex][charIndex]);
          setCharIndex(i => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines(prev => [...prev, lines[lineIndex]]);
          setCurrentLine('');
          setCharIndex(0);
          setLineIndex(i => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine('');
        setCharIndex(0);
        setLineIndex(0);
        setLoop(l => l + 1);
      }, 2500);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  const renderLine = (line, withCursor = false) => {
    const [varName, eq, value] = line.split(/ = (.+)/); // split once on first equals
    return (
      <div className={`whitespace-pre w-fit ${withCursor ? 'border-r-2 border-gray-400 animate-blink' : ''}`}>
        <span className="text-[#9CDCFE]">{varName}</span>
        <span className="text-[#d4d4d4]"> = </span>
        <span className={value.startsWith('"') ? 'text-[#ce9178]' : 'text-[#b5cea8]'}>{value}</span>
      </div>
    );
  };

  return (
    <div className="bg-[#1e1e1e] text-[#d4d4d4] min-h-screen flex items-center justify-center font-mono text-xl p-6">
      <div className="space-y-2 text-left">
        {typedLines.map((line, idx) => (
          <div key={`typed-${loop}-${idx}`}>{renderLine(line)}</div>
        ))}
        {lineIndex < lines.length && (
          <div key={`current-${loop}-${lineIndex}`}>{renderLine(currentLine, true)}</div>
        )}
      </div>
    </div>
  );
}
